	finalPath := filepath.Join(c.dir, filename)

	tmpFile, err := os.CreateTemp(c.dir, ".upload-*")
	if err != nil {
		return fmt.Errorf("failed to create temporary file in %s: %w", c.dir, err)
	}
	tmpPath := tmpFile.Name()
	tmpMetaPath := c.metaPath + ".tmp"

	// Cleanup on error
